  useEffect(() => {
    if (path === undefined) return
    let cancelled = false
    lastDirtyRef.current = null
    setContent(null)
    setError(null)
    setDirty(false)
    setTruncated(false)
    setWritable(true)
    setSavedAt(null)
    codeRef.current = null
    setCanUndo(false)
    setCanRedo(false)
    void (async () => {
      try {
        const response = await fetch('/desk-editor/fs.read', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ sessionId, path }),
